insert into characters(slug,full_name,first_name,rank,nature_types,fighting_style,summary,biography,has_spoilers,village_id,clan_id) values ('naruto-uzumaki','Naruto Uzumaki','Naruto','Hokage (Seventh)',array['Wind'],'Ninjutsu-focused, relies on Shadow Clones and Rasengan','A Konoha orphan who dreams of becoming Hokage and grows from a loud outcast into the village''s leader.','{"childhood":"Grows up alone in Konoha, seeking recognition from a village that keeps its distance.","genin":"Joins Team 7 and begins forming the bonds that define him.","events":"Trains under Jiraiya, returns to face the Akatsuki, and later fights in the Fourth Great Ninja War."}'::jsonb,true,(select id from villages where slug='konohagakure'),(select id from clans where slug='uzumaki'));
